package com.client.multichatwindows.config.ui; import com.client.multichatwindows.config.*; import com.client.multichatwindows.config.model.*; import net.minecraft.client.*; import net.minecraft.client.gui.*; import net.minecraft.client.gui.screen.Screen; import net.minecraft.text.Text; public class ConfigHomeScreen extends ScrollableDarkScreen { private final Screen parent; private GlobalConfig cfg; public ConfigHomeScreen(Screen parent){super(Text.translatable("multichatwindows.title"));this.parent=parent;} @Override protected void init(){ConfigManager.init();cfg=ConfigManager.global();clearChildren();int cx=width/2,y=46;addDrawableChild(new DarkButton(cx-110,y,220,20,Text.translatable(cfg.enabled?"multichatwindows.enabled.on":"multichatwindows.enabled.off"),()->{boolean wasEnabled=cfg.enabled;cfg.enabled=!cfg.enabled;ConfigManager.saveGlobal();if(!wasEnabled&&cfg.enabled){com.client.multichatwindows.hud.WindowService.importDisabledBacklogAndClearVanillaChat();}init();}));y+=26;addDrawableChild(new DarkButton(cx-110,y,220,20,Text.translatable("multichatwindows.language.current",Text.translatable(langKey(cfg.language))),()->{cfg.language=nextLang(cfg.language);applyMinecraftLanguage(cfg.language);ConfigManager.saveGlobal();MinecraftClient.getInstance().setScreen(new ConfigHomeScreen(parent));}));y+=26;addDrawableChild(new DarkButton(cx-110,y,220,20,Text.translatable(cfg.autoAddServer?"multichatwindows.auto_add_server.on":"multichatwindows.auto_add_server.off"),()->{cfg.autoAddServer=!cfg.autoAddServer;ConfigManager.saveGlobal();init();}));y+=26;addDrawableChild(new DarkButton(cx-110,y,220,20,Text.translatable("multichatwindows.servers.open"),()->MinecraftClient.getInstance().setScreen(new ServersScreen(this))));y+=26;addDrawableChild(new DarkButton(cx-110,y,220,20,Text.translatable(cfg.debug?"multichatwindows.debug.on":"multichatwindows.debug.off"),()->{cfg.debug=!cfg.debug;ConfigManager.saveGlobal();init();}));addDrawableChild(new DarkButton(cx-110,height-28,220,20,Text.translatable("multichatwindows.back"),()->MinecraftClient.getInstance().setScreen(parent)));} @Override public void render(DrawContext ctx,int mouseX,int mouseY,float delta){super.render(ctx,mouseX,mouseY,delta);ctx.drawCenteredTextWithShadow(textRenderer,Text.translatable("multichatwindows.title"),width/2,14,0xFFFFFFFF);ctx.drawCenteredTextWithShadow(textRenderer,Text.translatable("multichatwindows.config.subtitle"),width/2,28,0xFFB0B0B0);} private static Language nextLang(Language cur){Language[] vals=Language.values();int idx=cur==null?0:cur.ordinal();return vals[(idx+1)%vals.length];} private static String langKey(Language lang){return lang==Language.DE_DE?"multichatwindows.language.de":"multichatwindows.language.en";} private static void applyMinecraftLanguage(Language lang){MinecraftClient mc=MinecraftClient.getInstance();String code=lang==Language.DE_DE?"de_de":"en_us";mc.options.language=code;mc.getLanguageManager().setLanguage(code);mc.getLanguageManager().reload(mc.getResourceManager());mc.options.write();} }
